# Spoonacular Recipe & Food API
import requests

SPOONACULAR_API_KEY = "8d04b28e6c63af380c99c6303fe80c550097defa"
BASE_URL = "https://api.spoonacular.com"

def search_recipes(query, diet=None, intolerances=None, max_ready_time=None):
    """Search for recipes by criteria"""
    params = {
        "apiKey": SPOONACULAR_API_KEY,
        "query": query,
        "number": 10,
        "instructionsRequired": True,
        "addRecipeInformation": True
    }

    if diet:
        params["diet"] = diet
    if intolerances:
        params["intolerances"] = intolerances
    if max_ready_time:
        params["maxReadyTime"] = max_ready_time

    response = requests.get(f"{BASE_URL}/recipes/complexSearch", params=params)
    return response.json()

def get_recipe_details(recipe_id):
    """Get detailed recipe information"""
    response = requests.get(
        f"{BASE_URL}/recipes/{recipe_id}/information",
        params={"apiKey": SPOONACULAR_API_KEY}
    )
    return response.json()

def generate_meal_plan(diet, target_calories, time_frame="day"):
    """Generate a personalized meal plan"""
    response = requests.get(
        f"{BASE_URL}/mealplanner/generate",
        params={
            "apiKey": SPOONACULAR_API_KEY,
            "timeFrame": time_frame,
            "targetCalories": target_calories,
            "diet": diet
        }
    )
    return response.json()

def get_recipe_nutrition(recipe_id):
    """Get nutrition information for a recipe"""
    response = requests.get(
        f"{BASE_URL}/recipes/{recipe_id}/nutritionWidget.json",
        params={"apiKey": SPOONACULAR_API_KEY}
    )
    return response.json()

def find_by_ingredients(ingredients, strict=True):
    """Find recipes by available ingredients"""
    response = requests.get(
        f"{BASE_URL}/recipes/findByIngredients",
        params={
            "apiKey": SPOONACULAR_API_KEY,
            "ingredients": ",".join(ingredients),
            "number": 10,
            "ignorePantry": True,
            "ranking": 2
        }
    )
    return response.json()
